  1→import { Form, Head } from '@inertiajs/react';
  2→import InputError from '@/components/input-error';
  3→import PasswordInput from '@/components/password-input';
  4→import TextLink from '@/components/text-link';
  5→import { Button } from '@/components/ui/button';
  6→import { Checkbox } from '@/components/ui/checkbox';
  7→import { Input } from '@/components/ui/input';
  8→import { Label } from '@/components/ui/label';
  9→import { Spinner } from '@/components/ui/spinner';
 10→import { useTranslation } from '@/hooks/use-translation';
 11→import AuthLayout from '@/layouts/auth-layout';
 12→import { register } from '@/routes';
 13→import { store } from '@/routes/login';
 14→import { request } from '@/routes/password';
 15→
 16→type Props = {
 17→    status?: string;
 18→    canResetPassword: boolean;
 19→    canRegister: boolean;
 20→};
 21→
 22→export default function Login({
 23→    status,
 24→    canResetPassword,
 25→    canRegister,
 26→}: Props) {
 27→    const { t } = useTranslation();
 28→
 29→    return (
 30→        <AuthLayout
 31→            title={t('login.title')}
 32→            description={t('login.description')}
 33→        >
 34→            <Head title={t('login.head_title')} />
 35→
 36→            <Form
 37→                {...store.form()}
 38→                resetOnSuccess={['password']}
 39→                className="flex flex-col gap-6"
 40→            >
 41→                {({ processing, errors }) => (
 42→                    <>
 43→                        <div className="grid gap-6">
 44→                            <div className="grid gap-2">
 45→                                <Label htmlFor="email">{t('login.email')}</Label>
 46→                                <Input
 47→                                    id="email"
 48→                                    type="email"
 49→                                    name="email"
 50→                                    required
 51→                                    autoFocus
 52→                                    tabIndex={1}
 53→                                    autoComplete="email"
 54→                                    placeholder="email@example.com"
 55→                                />
 56→                                <InputError message={errors.email} />
 57→                            </div>
 58→
 59→                            <div className="grid gap-2">
 60→                                <div className="flex items-center">
 61→                                    <Label htmlFor="password">{t('login.password')}</Label>
 62→                                    {canResetPassword && (
 63→                                        <TextLink
 64→                                            href={request()}
 65→                                            className="ml-auto text-sm"
 66→                                            tabIndex={5}
 67→                                        >
 68→                                            {t('login.forgot_password')}
 69→                                        </TextLink>
 70→                                    )}
 71→                                </div>
 72→                                <PasswordInput
 73→                                    id="password"
 74→                                    name="password"
 75→                                    required
 76→                                    tabIndex={2}
 77→                                    autoComplete="current-password"
 78→                                    placeholder={t('login.password_placeholder')}
 79→                                />
 80→                                <InputError message={errors.password} />
 81→                            </div>
 82→
 83→                            <div className="flex items-center space-x-3">
 84→                                <Checkbox
 85→                                    id="remember"
 86→                                    name="remember"
 87→                                    tabIndex={3}
 88→                                />
 89→                                <Label htmlFor="remember">{t('login.remember_me')}</Label>
 90→                            </div>
 91→
 92→                            <Button
 93→                                type="submit"
 94→                                className="mt-4 w-full"
 95→                                tabIndex={4}
 96→                                disabled={processing}
 97→                                data-test="login-button"
 98→                            >
 99→                                {processing && <Spinner />}
100→                                {t('login.submit')}
101→                            </Button>
102→                        </div>
103→
104→                        {canRegister && (
105→                            <div className="text-center text-sm text-muted-foreground">
106→                                {t('login.no_account')}{' '}
107→                                <TextLink href={register()} tabIndex={5}>
108→                                    {t('login.sign_up')}
109→                                </TextLink>
110→                            </div>
111→                        )}
112→                    </>
113→                )}
114→            </Form>
115→
116→            {status && (
117→                <div className="mb-4 text-center text-sm font-medium text-green-600">
118→                    {status}
119→                </div>
120→            )}
121→        </AuthLayout>
122→    );
123→}
