 1→import { Eye, EyeOff } from 'lucide-react';
 2→import type { ComponentProps, Ref } from 'react';
 3→import { useState } from 'react';
 4→import { Input } from '@/components/ui/input';
 5→import { useTranslation } from '@/hooks/use-translation';
 6→import { cn } from '@/lib/utils';
 7→
 8→export default function PasswordInput({
 9→    className,
10→    ref,
11→    ...props
12→}: Omit<ComponentProps<'input'>, 'type'> & { ref?: Ref<HTMLInputElement> }) {
13→    const [showPassword, setShowPassword] = useState(false);
14→    const { t } = useTranslation();
15→
16→    return (
17→        <div className="relative">
18→            <Input
19→                type={showPassword ? 'text' : 'password'}
20→                className={cn('pr-10', className)}
21→                ref={ref}
22→                {...props}
23→            />
24→            <button
25→                type="button"
26→                onClick={() => setShowPassword((prev) => !prev)}
27→                className="absolute inset-y-0 right-0 flex items-center rounded-r-md px-3 text-muted-foreground hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring focus-visible:outline-none"
28→                aria-label={showPassword ? t('password_input.hide') : t('password_input.show')}
29→                tabIndex={-1}
30→            >
31→                {showPassword ? (
32→                    <EyeOff className="size-4" />
33→                ) : (
34→                    <Eye className="size-4" />
35→                )}
36→            </button>
37→        </div>
38→    );
39→}
