 16→export default function TwoFactorChallenge() {
 17→    const [showRecoveryInput, setShowRecoveryInput] = useState<boolean>(false);
 18→    const [code, setCode] = useState<string>('');
 19→
 20→    const authConfigContent = useMemo<{
 21→        title: string;
 22→        description: string;
 23→        toggleText: string;
 24→    }>(() => {
 25→        if (showRecoveryInput) {
 26→            return {
 27→                title: 'Recovery code',
 28→                description:
 29→                    'Please confirm access to your account by entering one of your emergency recovery codes.',
 30→                toggleText: 'login using an authentication code',
 31→            };
 32→        }
 33→
 34→        return {
 35→            title: 'Authentication code',
 36→            description:
 37→                'Enter the authentication code provided by your authenticator application.',
 38→            toggleText: 'login using a recovery code',
 39→        };
 40→    }, [showRecoveryInput]);
 41→
 42→    const toggleRecoveryMode = (clearErrors: () => void): void => {
 43→        setShowRecoveryInput(!showRecoveryInput);
 44→        clearErrors();
 45→        setCode('');
 46→    };
 47→
 48→    return (
 49→        <AuthLayout
 50→            title={authConfigContent.title}
 51→            description={authConfigContent.description}
 52→        >
 53→            <Head title="Two-factor authentication" />
 54→
 55→            <div className="space-y-6">
 56→                <Form
 57→                    {...store.form()}
 58→                    className="space-y-4"
 59→                    resetOnError
 60→                    resetOnSuccess={!showRecoveryInput}
 61→                >
 62→                    {({ errors, processing, clearErrors }) => (
 63→                        <>
 64→                            {showRecoveryInput ? (
 65→                                <>
 66→                                    <Input
 67→                                        name="recovery_code"
 68→                                        type="text"
 69→                                        placeholder="Enter recovery code"
 70→                                        autoFocus={showRecoveryInput}
 71→                                        required
 72→                                    />
 73→                                    <InputError
 74→                                        message={errors.recovery_code}
 75→                                    />
 76→                                </>
 77→                            ) : (
 78→                                <div className="flex flex-col items-center justify-center space-y-3 text-center">
 79→                                    <div className="flex w-full items-center justify-center">
 80→                                        <InputOTP
 81→                                            name="code"
 82→                                            maxLength={OTP_MAX_LENGTH}
 83→                                            value={code}
 84→                                            onChange={(value) => setCode(value)}
 85→                                            disabled={processing}
 86→                                            pattern={REGEXP_ONLY_DIGITS}
 87→                                        >
 88→                                            <InputOTPGroup>
 89→                                                {Array.from(
 90→                                                    { length: OTP_MAX_LENGTH },
 91→                                                    (_, index) => (
 92→                                                        <InputOTPSlot
 93→                                                            key={index}
 94→                                                            index={index}
 95→                                                        />
 96→                                                    ),
 97→                                                )}
 98→                                            </InputOTPGroup>
 99→                                        </InputOTP>
100→                                    </div>
101→                                    <InputError message={errors.code} />
102→                                </div>
103→                            )}
104→
105→                            <Button
106→                                type="submit"
107→                                className="w-full"
108→                                disabled={processing}
109→                            >
110→                                Continue
111→                            </Button>
112→
113→                            <div className="text-center text-sm text-muted-foreground">
114→                                <span>or you can </span>
115→                                <button
116→                                    type="button"
117→                                    className="cursor-pointer text-foreground underline decoration-neutral-300 underline-offset-4 transition-colors duration-300 ease-out hover:decoration-current! dark:decoration-neutral-500"
118→                                    onClick={() =>
